"use client";
import { useState} from 'react';
import { Link , useNavigate } from "@tanstack/react-router";


export default function Navbar() {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  
  const navigation = useNavigate();

  const submitInLogo = () => {
    setTimeout(() => {
      setLoading(true);
      setError(null);
    }, 0);

    setTimeout(() => {
      setLoading(false);
      navigation({ to: "/" });
    }, 2000);
  }
 
  return (
    <>
      {loading && (
        <div className="fixed  inset-0 z-[9999] flex flex-col bg-white/70 backdrop-blur-sm">
          <div className="w-16 h-16 border-4 border-[#cf4a27] rounded-full animate-spin shadow-lg"></div>
          <p className="mt-4 text-[#cf4a27] font-bold text-xl animate-pulse tracking-wide">Loading...</p>
        </div>
      )}
      <nav className="flex justify-between items-center w-full px-8 py-3 border-b border-gray-100 bg-white relative z-50">
        {/* Left Section: Logo & Navigation */}
        <div className="flex items-center gap-12">
          {/* Logo */}
          <div className="flex  gap-2 cursor-pointer">
            <svg width="28" height="28" viewBox="0 0 32 32" fill="none" xmlns="http://www.w3.org/2000/svg">
              <circle cx="16" cy="16" r="14" fill="#cf4a27" fillOpacity="0.1" />
              <circle cx="16" cy="16" r="8" fill="#cf4a27" />
              <path d="M22 10 A 2 2 0 1 1 22 14 A 2 2 0 1 1 22 10" fill="#cf4a27" />
            </svg>
            <Link
              onClick={submitInLogo} to='/' className="text-[20px] left-0  font-bold text-[#cf4a27] tracking-tight">Food Cut</Link>
          </div>
        </div>

        {/* Right Section: Search, Location & Profile */}
        <div className="flex gap-6">
          {/* Search Bar */}
          <div className="hidden lg:flex items-center bg-gray-100 rounded-full px-4 py-2.5 w-[300px]">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 text-gray-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
            </svg>
            <input
              type="text"
              placeholder="Search for dishes or restaurant..."
              className="bg-transparent border-none outline-none text-[14px] text-gray-700 ml-2 w-full placeholder-gray-400"
            />
          </div>
          <div className="flex gap-4 justify-center items-center ">
          <Link to="/auth/login">Login In</Link>
            <Link to="/auth/register" className="bg-amber-400 rounded-2xl px-5 py-2.5 ">Sign In</Link>
          </div>
        </div>
        
      </nav>
    </>
  );
}
